def transform(g):
    hh,ww=len(g),len(g[0])
    zmap=[[1 if g[i][j]==0 else 0 for j in range(ww)] for i in range(hh)]
    pockets=[]; seen=set()
    for i in range(hh):
        for j in range(ww):
            if zmap[i][j] and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c=[]
                while st:
                    y,x=st.pop(); c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<hh and 0<=nx<ww and zmap[ny][nx] and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                pockets.append(c)
    sizes=[len(c) for c in pockets]; mn,mx=min(sizes),max(sizes)
    out=[row[:] for row in g]
    for c in pockets:
        col=8 if len(c)==mx else 7 if len(c)==mn else 0
        if col:
            for i,j in c: out[i][j]=col
    return out
